-- Import certDefs, certCategories, boatCategories config values from the
-- Google Sheets export (mainsheet -> config.csv), same source/date as the
-- boats/locations import. Direct app_config upsert (equivalent to what
-- save_config_value/save_config_list_item do at the DB level) since this
-- is bulk seeding, not a per-item admin edit -- existing item ids (e.g.
-- certDefs) are preserved as-is so boats.access_gate_cert references
-- (cert_mok1v4ud, cert_mnuhq6w5) keep resolving.

insert into public.app_config (key, value, updated_at) values ('certCategories', '["Operator License", "First Aid", "Safeguarding", "Coaching/Race Management Qualifications", "Educational Qualifications"]'::jsonb, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();

